// RevenueCat webhook authentication — implemented against the documented mechanisms only:
//   1. the Authorization header value configured in the RevenueCat dashboard, sent verbatim with every POST;
//   2. optional HMAC signing: `X-RevenueCat-Webhook-Signature: t=<unix seconds>,v1=<hex>` where
//      v1 = HMAC-SHA256(signingSecret, "<t>.<raw request body>"), computed over the ORIGINAL bytes (never re-serialised JSON).
// `t` is regenerated by RevenueCat on every delivery attempt, so it bounds replay of a *captured request*; event-id dedupe
// (premium_events UNIQUE (environment, event_id)) bounds replay of an *event*. Nothing here invents a header or accepts the
// client-public SDK key as a credential.

export const SIGNATURE_HEADER = 'x-revenuecat-webhook-signature';
export const DEFAULT_TOLERANCE_SECONDS = 300;

const encoder = new TextEncoder();

async function sha256(value: string): Promise<Uint8Array> {
  return new Uint8Array(await crypto.subtle.digest('SHA-256', encoder.encode(value)));
}

/** Constant-time string equality: both sides are hashed first, so neither length nor content steers the comparison time. */
export async function constantTimeEqual(a: string, b: string): Promise<boolean> {
  const [ha, hb] = await Promise.all([sha256(a), sha256(b)]);
  let diff = 0;
  for (let i = 0; i < ha.length; i += 1) diff |= ha[i] ^ hb[i];
  return diff === 0;
}

function toHex(bytes: Uint8Array): string {
  let out = '';
  for (const byte of bytes) out += byte.toString(16).padStart(2, '0');
  return out;
}

export async function hmacSha256Hex(secret: string, message: Uint8Array<ArrayBuffer>): Promise<string> {
  const key = await crypto.subtle.importKey('raw', encoder.encode(secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  return toHex(new Uint8Array(await crypto.subtle.sign('HMAC', key, message)));
}

/** RevenueCat's client-public SDK keys must never be accepted (or configured) as a webhook credential. */
export function looksLikePublicSdkKey(value: string): boolean {
  return /^(appl|goog|amzn|stripe|rcb|roku|paddle|test)_[A-Za-z0-9]{8,}$/.test(value.trim());
}

export interface WebhookAuthConfig {
  /** The Authorization header value configured in the dashboard. Required. */
  authorizationSecret: string | null;
  /** The HMAC signing secret, when HMAC signing is enabled for the integration. */
  hmacSecret: string | null;
  /** Production must sign; an unsigned production deployment is a configuration error, not a fallback. */
  requireHmac: boolean;
  toleranceSeconds: number;
}

export type WebhookAuthFailure =
  | 'misconfigured'
  | 'missing_authorization'
  | 'bad_authorization'
  | 'missing_signature'
  | 'malformed_signature'
  | 'stale_signature'
  | 'bad_signature';

export type WebhookAuthResult = { ok: true; hmacVerified: boolean } | { ok: false; reason: WebhookAuthFailure };

export function webhookConfigProblem(config: WebhookAuthConfig): string | null {
  if (!config.authorizationSecret || config.authorizationSecret.length < 16) return 'authorization secret missing or too short';
  if (looksLikePublicSdkKey(config.authorizationSecret)) return 'authorization secret looks like a public SDK key';
  if (config.hmacSecret !== null && looksLikePublicSdkKey(config.hmacSecret)) return 'hmac secret looks like a public SDK key';
  if (config.requireHmac && (!config.hmacSecret || config.hmacSecret.length < 16)) return 'hmac signing is required but no signing secret is configured';
  return null;
}

/** Parses `t=<unix>,v1=<hex>[,v1=<hex>]`. Several v1 values are accepted so a secret rotation can overlap. */
export function parseSignatureHeader(value: string): { t: number; v1: string[] } | null {
  let t: number | null = null;
  const v1: string[] = [];
  for (const part of value.split(',')) {
    const index = part.indexOf('=');
    if (index < 0) return null;
    const key = part.slice(0, index).trim();
    const val = part.slice(index + 1).trim();
    if (key === 't') {
      if (!/^\d{1,12}$/.test(val)) return null;
      t = Number(val);
    } else if (key === 'v1') {
      if (!/^[0-9a-f]{64}$/i.test(val)) return null;
      v1.push(val.toLowerCase());
    }
  }
  return t === null || v1.length === 0 ? null : { t, v1 };
}

export async function verifyWebhookRequest(input: {
  rawBody: Uint8Array;
  authorizationHeader: string | null;
  signatureHeader: string | null;
  config: WebhookAuthConfig;
  nowMs: number;
}): Promise<WebhookAuthResult> {
  const { config } = input;
  if (webhookConfigProblem(config) !== null) return { ok: false, reason: 'misconfigured' };

  if (!input.authorizationHeader) return { ok: false, reason: 'missing_authorization' };
  // Compare BOTH credentials before deciding, so a wrong authorization header and a wrong signature take the same path length.
  const authOk = await constantTimeEqual(input.authorizationHeader, config.authorizationSecret as string);

  let signatureResult: WebhookAuthFailure | 'ok' | 'not_required' = 'not_required';
  if (config.hmacSecret !== null) {
    if (!input.signatureHeader) signatureResult = 'missing_signature';
    else {
      const parsed = parseSignatureHeader(input.signatureHeader);
      if (parsed === null) signatureResult = 'malformed_signature';
      else if (Math.abs(Math.floor(input.nowMs / 1000) - parsed.t) > config.toleranceSeconds) signatureResult = 'stale_signature';
      else {
        const prefix = encoder.encode(`${parsed.t}.`);
        const message = new Uint8Array(prefix.length + input.rawBody.length);
        message.set(prefix, 0);
        message.set(input.rawBody, prefix.length);
        const expected = await hmacSha256Hex(config.hmacSecret, message);
        let matched = false;
        for (const candidate of parsed.v1) if (await constantTimeEqual(candidate, expected)) matched = true;
        signatureResult = matched ? 'ok' : 'bad_signature';
      }
    }
  }

  if (!authOk) return { ok: false, reason: 'bad_authorization' };
  if (signatureResult !== 'ok' && signatureResult !== 'not_required') return { ok: false, reason: signatureResult };
  return { ok: true, hmacVerified: signatureResult === 'ok' };
}
